const API_BASE_URL = (() => {
  const params = new URLSearchParams(location.search);
  let stored = null;
  try { stored = localStorage.getItem('FINN_API_BASE_URL'); } catch {}
  const configured = window.FINN_CONFIG?.apiBaseUrl || params.get('apiBase') || stored;
  const raw = configured || (['http:', 'https:'].includes(location.protocol) ? location.origin : '');
  return raw ? raw.replace(/\/$/, '') : '';
})();

