function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function safeUrl(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
function companyByTicker(ticker){return companies.find(c=>c.ticker===ticker)||researchUniverse.find(c=>c.ticker===ticker)||null}
function mapCompany(c){return {...c,monogram:c.monogram||String(c.name||c.ticker).split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase(),business:c.business||'Business profile will appear when verified company-source material is connected.',segments:c.segments||[]}}
function renderHoldings(){document.getElementById('holdingList').innerHTML=companies.map(c=>`<button class="holding ${selectedCompany&&c.ticker===selectedCompany.ticker?'selected':''}" data-ticker="${escapeHtml(c.ticker)}" title="${escapeHtml(c.name)}"><span class="holding-logo">${escapeHtml(c.monogram)}</span><span class="holding-name">${escapeHtml(c.name)}</span><span class="holding-ticker">${escapeHtml(c.ticker)}</span></button>`).join('')||'<div class="holding-empty">No portfolio companies loaded</div>';document.getElementById('holdingCount').textContent=companies.length}
function renderActivity(){
  const priority=document.getElementById('priorityFilter').value,category=document.getElementById('categoryFilter').value;
  const source=dataMode==='live'?digestAnnouncements:announcements;
  let list=source.filter(a=>(showRoutine||a.priority!=='routine')&&(priority==='all'||a.priority===priority)&&(category==='all'||a.category===category));
  document.getElementById('activityList').innerHTML=list.length?list.map(a=>{const attachment=safeUrl(a.attachment_url)||safeUrl(a.source_page_url);const result=a.results_context;const resultHtml=result?.status==='available'?`<div class="result-strip"><span>${escapeHtml(result.metrics.revenue?`Revenue ₹${Number(result.metrics.revenue.value_in_crore).toLocaleString('en-IN')} Cr`:'' )}</span><span>${escapeHtml(result.metrics.pbt?`PBT ₹${Number(result.metrics.pbt.value_in_crore).toLocaleString('en-IN')} Cr`:'' )}</span><span>${escapeHtml(result.metrics.pat?`PAT ₹${Number(result.metrics.pat.value_in_crore).toLocaleString('en-IN')} Cr`:'' )}</span><button data-result-company="${escapeHtml(a.ticker)}">Open financial research ↗</button></div>`:result?.status==='extraction_unavailable'?`<div class="result-strip result-unavailable">${escapeHtml(result.message)}</div>`:'';return `<article class="activity-item" data-id="${escapeHtml(a.id)}"><div class="activity-symbol ${escapeHtml(a.tone||'')}">${escapeHtml(a.icon||'▤')}</div><div class="activity-main"><div class="activity-top"><strong>${escapeHtml(a.company)}</strong><span class="activity-ticker">${escapeHtml(a.ticker)}</span><span class="activity-category">${escapeHtml(a.category)}</span><span class="activity-priority ${escapeHtml(a.priority)}">${dataMode==='live'?escapeHtml(a.priority.toUpperCase()):escapeHtml(a.priority.toUpperCase())}</span></div><h3 class="activity-title">${escapeHtml(a.title)}</h3><p class="activity-summary">${escapeHtml(dataMode==='live'?a.materiality_reason:a.summary||'No issuer details were included with this filing.')}</p>${resultHtml}<div class="activity-bottom"><span class="source-text">${escapeHtml(a.source)}</span><span>·</span><span>${escapeHtml(a.time)}</span>${attachment?`<a class="source-link" href="${escapeHtml(attachment)}" target="_blank" rel="noopener noreferrer">Open original ↗</a>`:''}</div></div><button class="bookmark ${savedIds.has(a.id)?'saved':''}" aria-label="${savedIds.has(a.id)?'Remove saved item':'Save item'}" data-save="${escapeHtml(a.id)}">${savedIds.has(a.id)?'◆':'♧'}</button></article>`}).join(''):`<div class="empty-filter">${announcementError?escapeHtml(announcementError):dataMode==='live'?'No dated portfolio announcements fall inside this window.':'No announcements match these filters.'}</div>`;
  document.getElementById('feedTotal').textContent=`${list.length} ${list.length===1?'item':'items'}`;
  const routineCount=source.filter(a=>a.priority==='routine').length;
  document.getElementById('loadMore').textContent=showRoutine?'Hide routine items ↑':`Show ${routineCount} routine filings ↓`;
  document.getElementById('loadMore').style.display=routineCount?'block':'none';
  document.querySelectorAll('.activity-item').forEach(row=>row.addEventListener('click',e=>{if(e.target.closest('[data-save],a'))return;openDetail(row.dataset.id)}));
  document.querySelectorAll('[data-result-company]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();selectCompany(b.dataset.resultCompany);showView('research');document.getElementById('financialMetrics').scrollIntoView({behavior:'smooth',block:'center'})}));
  document.querySelectorAll('[data-save]').forEach(button=>button.addEventListener('click',e=>{e.stopPropagation();const id=button.dataset.save;savedIds.has(id)?savedIds.delete(id):savedIds.add(id);renderActivity();renderSaved();toast(savedIds.has(id)?'Saved to your reading list':'Removed from saved items')}));
}
function renderSaved(){const present=[...savedIds].filter(id=>announcements.some(a=>String(a.id)===String(id)));savedIds=new Set(present);document.getElementById('savedCount').textContent=savedIds.size;document.getElementById('savedEmpty').style.display=savedIds.size?'none':'flex';document.getElementById('savedList').innerHTML=[...savedIds].map(id=>{const a=announcements.find(x=>String(x.id)===String(id));return `<div class="saved-row">${escapeHtml(a.company)} · ${escapeHtml(a.title)}<button data-unsave="${escapeHtml(id)}" aria-label="Remove ${escapeHtml(a.company)}">×</button></div>`}).join('');document.querySelectorAll('[data-unsave]').forEach(b=>b.addEventListener('click',()=>{savedIds.delete(b.dataset.unsave);renderSaved();renderActivity()}))}
function openDetail(id){const a=announcements.find(x=>String(x.id)===String(id));if(!a)return;const sourceUrl=safeUrl(a.attachment_url)||safeUrl(a.source_page_url);const copy=dataMode==='live'?a.summary||'The exchange filing did not provide additional issuer details.':a.detail;const provenance=dataMode==='live'?`<strong>Source</strong><br>${escapeHtml(a.source)} · ${escapeHtml(a.time)}<br><strong>Status</strong><br>New · Not yet assessed`:`<strong>Why surfaced</strong><br>${escapeHtml(a.why)}<br><br><strong>Source</strong><br>${escapeHtml(a.source)} · ${escapeHtml(a.time)}<br><span style="color:#74847f">Illustrative demo item; no live filing attached.</span>`;document.getElementById('dialogContent').innerHTML=`<div class="dialog-label">${escapeHtml(a.category.toUpperCase())} · ${escapeHtml(a.company.toUpperCase())}</div><h2 class="dialog-title">${escapeHtml(a.title)}</h2><p class="dialog-copy">${escapeHtml(copy)}</p><div class="dialog-data">${provenance}${sourceUrl?`<br><br><a href="${escapeHtml(sourceUrl)}" target="_blank" rel="noopener noreferrer">Open original source ↗</a>`:''}</div><div class="dialog-actions"><button data-dialog-company="${escapeHtml(a.ticker)}">Open company research ↗</button><button data-dialog-save="${escapeHtml(a.id)}">${savedIds.has(a.id)?'Remove saved':'Save for later'}</button></div>`;document.getElementById('detailDialog').showModal();document.querySelector('[data-dialog-company]').addEventListener('click',()=>{selectCompany(a.ticker);showView('research');document.getElementById('detailDialog').close()});document.querySelector('[data-dialog-save]').addEventListener('click',()=>{savedIds.has(a.id)?savedIds.delete(a.id):savedIds.add(a.id);renderSaved();renderActivity();toast(savedIds.has(a.id)?'Saved to your reading list':'Removed from saved items')})}
let researchCoverage=null;
async function loadResearchCoverage(ticker){const panel=document.getElementById('coveragePanel');panel.innerHTML='<span>Loading company coverage…</span>';try{const data=await apiGet(`/api/research-coverage/${encodeURIComponent(ticker)}`);if(dataMode!=='live'||selectedCompany?.ticker!==ticker)return;researchCoverage=data;const labels={eod_market_data:'EOD market data',exchange_announcements:'NSE announcements',official_business_profile:'Official business profile',annual_reports:'Annual reports',quarterly_results:'Financial results',earnings_call_transcripts:'Concall transcripts',indexed_document_pages:'Indexed pages',validated_financial_observations:'Validated financial observations',management_statements_and_commitments:'Management statements'};panel.innerHTML=Object.entries(data.states).map(([key,state])=>`<div class="coverage-row"><span>${escapeHtml(labels[key]||key)}</span><b data-state="${escapeHtml(state)}">${escapeHtml(state.replaceAll('_',' '))}</b></div>`).join('');const report=data.states.annual_reports;document.getElementById('sourceCoverageTitle').textContent=report==='available'?`${data.company} · research sources available`:report==='not_connected'?`${data.company} · limited research coverage`:`${data.company} · ${report.replaceAll('_',' ')}`;document.getElementById('sourceCoverageText').textContent=report==='not_connected'?'Market and exchange data may be available, but no official annual report is connected; financial statements cannot be shown yet.':report==='indexed_not_extracted'?'The report is indexed, but financial extraction has not been performed.':report==='needs_review'?'Financial extraction exists and awaits source validation.':report==='provider_error'?'The official source provider returned an error; this is not an empty-data result.':'Statuses below come from stored sources and extraction records.'}catch(e){if(dataMode!=='live'||selectedCompany?.ticker!==ticker)return;panel.innerHTML=`<span class="coverage-error">Coverage API failure: ${escapeHtml(e.message)}</span>`;document.getElementById('sourceCoverageTitle').textContent='Coverage service unavailable';document.getElementById('sourceCoverageText').textContent='Unable to determine source coverage because the backend request failed.'}}
function selectCompany(ticker){const next=companyByTicker(ticker);if(!next)return;selectionGeneration++;financialDataTicker=null;financialAnalysis=null;thesisDrift=null;thesisDriftError=null;financialHeadline=null;selectedCompany=next;renderCompany();renderHoldings();document.getElementById('companySearch').value='';if(dataMode==='live')loadCompanyMarket(next.ticker)}
function renderCompany(){const c=selectedCompany;if(!c){document.getElementById('companyName').textContent='No company data';document.getElementById('companyTicker').textContent='—';document.getElementById('companySector').textContent='Portfolio service unavailable';document.getElementById('businessDescription').textContent='Company data could not be loaded from the backend.';document.getElementById('segmentTags').innerHTML='';document.getElementById('companyDevelopments').innerHTML=`<div class="development-row"><div><strong>No live company records</strong><small>${escapeHtml(companyError||'Connect to the FINN API and try again.')}</small></div></div>`;sourceDocuments=[];renderDocuments();document.getElementById('companyLatestPrice').innerHTML='— <small>INR</small>';document.getElementById('companyPriceDate').textContent='No company selected';return}document.getElementById('companyName').textContent=c.name;document.getElementById('companyTicker').textContent=c.ticker;document.getElementById('companySector').textContent=c.sector||'Sector unavailable';document.getElementById('companyUniverseLabel').textContent=companies.some(x=>x.ticker===c.ticker)?'PORTFOLIO':'AD-HOC RESEARCH';document.querySelector('.company-monogram').textContent=c.monogram;document.getElementById('businessDescription').textContent=dataMode==='live'&&!c.business_source?`Official company profile is not yet extracted for ${c.ticker}.`:(c.business||'Official company profile is not yet extracted.');document.querySelector('.illustrative-inline').textContent=dataMode==='live'?(c.business_source||'Official source profile not yet extracted'):'Company profile · demo description';document.getElementById('segmentTags').innerHTML=dataMode==='live'&&!c.business_source?'':c.segments.map(s=>`<span>${escapeHtml(s)}</span>`).join('');const items=announcements.filter(a=>a.ticker===c.ticker);document.getElementById('companyDevelopments').innerHTML=items.length?items.slice(0,8).map(a=>`<div class="development-row"><span class="activity-symbol ${escapeHtml(a.tone||'')}">${escapeHtml(a.icon||'▤')}</span><div><strong>${escapeHtml(a.title)}</strong><small>${escapeHtml(a.category)} · ${escapeHtml(a.time)}${dataMode==='live'?' · unassessed':' · illustrative'}</small></div><button data-open="${escapeHtml(a.id)}" aria-label="Open ${escapeHtml(a.title)}">↗</button></div>`).join(''):`<div class="development-row"><span class="activity-symbol">—</span><div><strong>No announcements for this company</strong><small>${dataMode==='live'?'No current API records are available.':'No demo developments for this holding.'}</small></div></div>`;document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>openDetail(b.dataset.open)));if(dataMode==='live'){sourceDocuments=[];renderDocuments();loadCompanyProfile(c.ticker);loadResearchCoverage(c.ticker);loadCompanyDocuments(c.ticker);loadCompanyMarket(c.ticker);loadCompanyFinancials(c.ticker);loadManagement(c.ticker)}else{renderDocuments();renderFinancialPlaceholders('demo')}}
function formatDateTime(value){if(!value)return'—';const d=new Date(value);if(Number.isNaN(d.getTime()))return String(value);return new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'}).format(d)}
function mapAnnouncement(item){return {id:String(item.id),ticker:item.ticker,company:item.company,category:item.category||'other',priority:item.materiality||'routine',materiality_reason:item.materiality_reason||'',icon:'▤',tone:item.materiality==='high'?'high':item.materiality==='medium'?'monitor':'',title:item.subject,summary:item.details||'',detail:item.details||'',time:formatDateTime(item.announcement_datetime),source:`${item.exchange} announcement`,source_page_url:item.source_page_url,attachment_url:item.attachment_url,original_category:item.original_category,assessment_status:item.assessment_status,results_context:item.results_context||null}}
function renderDigestSummary(){if(dataMode!=='live'||!digestMeta)return;const c=digestMeta.counts||{};document.getElementById('digestRange').textContent=`${formatDateTime(digestMeta.from)} – ${formatDateTime(digestMeta.to_exclusive)} · Asia/Kolkata${digestMeta.undated_portfolio_announcements?` · ${digestMeta.undated_portfolio_announcements} undated filing${digestMeta.undated_portfolio_announcements===1?'':'s'} excluded`:''}`;document.getElementById('digestCounts').innerHTML=`<span><b>${digestMeta.total}</b> announcements</span><span><b>${c.high||0}</b> high</span><span><b>${c.medium||0}</b> medium</span><span><b>${c.routine||0}</b> routine</span>`;document.getElementById('signalHeading').textContent=`${c.high||0} high-priority developments`;document.getElementById('signalDescription').textContent=`${digestMeta.total} dated filings in this selected window, ranked by explainable rules.`;document.getElementById('signalHigh').textContent=c.high||0;document.getElementById('signalMedium').textContent=c.medium||0;document.getElementById('signalRoutine').textContent=c.routine||0;document.getElementById('signalNote').textContent='Priority reasons are rule-based and shown on each filing.';const first=digestAnnouncements.find(a=>a.priority==='high')||digestAnnouncements.find(a=>a.priority==='medium');if(first){document.getElementById('briefingCard').innerHTML=`<div class="briefing-index">01</div><div class="briefing-body"><div class="briefing-meta"><span class="company-chip tata-chip">${escapeHtml(first.ticker.slice(0,2))}</span><strong>${escapeHtml(first.company)}</strong><span class="ticker-label">NSE · ${escapeHtml(first.ticker)}</span><span class="meta-spacer"></span><span class="priority-dot ${first.priority==='high'?'high':''}"></span><span class="priority-word">${escapeHtml(first.priority.toUpperCase())}</span></div><h3>${escapeHtml(first.title)}</h3><p>${escapeHtml(first.materiality_reason)}</p><div class="briefing-foot"><span class="source-pill"><span class="file-glyph">▤</span>${escapeHtml(first.category.replaceAll('_',' '))}</span><span class="briefing-time">${escapeHtml(first.time)}</span><button class="investigate-button" data-open-briefing="${escapeHtml(first.id)}">Inspect <span>↗</span></button></div></div>`;document.querySelector('[data-open-briefing]')?.addEventListener('click',()=>openDetail(first.id))}else{document.getElementById('briefingCard').innerHTML='<div class="briefing-body"><h3>No high or medium filings in this window</h3><p>Routine filings remain available below. No older records were substituted.</p></div>'}}
async function loadDigest(){if(dataMode!=='live')return;const gen=++digestGeneration;const mode=document.getElementById('digestWindow').value;let query=`window=${encodeURIComponent(mode==='custom'?'24h':mode)}`;if(mode==='custom'){const from=document.getElementById('digestFrom').value,to=document.getElementById('digestTo').value;if(!from||!to)return toast('Choose both custom dates');query+=`&from_date=${encodeURIComponent(from)}&to_date=${encodeURIComponent(to)}`}document.getElementById('digestRange').textContent='Loading selected portfolio window…';try{const payload=await apiGet(`/api/digest?${query}`);if(dataMode!=='live'||gen!==digestGeneration)return;digestMeta=payload;digestAnnouncements=payload.items.map(mapAnnouncement);const categories=[...new Set(digestAnnouncements.map(a=>a.category))];setSelectOptions(document.getElementById('categoryFilter'),categories,'All categories');showRoutine=false;renderDigestSummary();renderActivity()}catch(e){if(gen!==digestGeneration)return;announcementError=`Digest unavailable: ${e.message}`;digestAnnouncements=[];digestMeta=null;renderActivity()}}
function renderAlertHistory(){const host=document.getElementById('alertHistory');if(!alertEvents.length){host.innerHTML='<div class="empty-filter">No rules have triggered in the available EOD and filing data.</div>';return}host.innerHTML=alertEvents.slice(0,5).map(a=>`<article class="alert-event"><div class="alert-event-top"><strong>${escapeHtml(a.company)}</strong><span>${escapeHtml(a.ticker)}</span><small>${escapeHtml(a.rule_type.replaceAll('_',' '))}</small></div><p>${escapeHtml(a.reason)}</p><small>${escapeHtml(formatDateTime(a.triggered_at))}${a.source_url?` · <a href="${escapeHtml(a.source_url)}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:''}</small></article>`).join('')}
async function refreshAlerts(){if(dataMode!=='live')return;try{await apiGet('/api/alerts/evaluate',{method:'POST'});const [settings,history]=await Promise.all([apiGet('/api/alerts/settings'),apiGet('/api/alerts')]);alertSettings=settings;alertEvents=history.items||[];renderAlertHistory()}catch(e){document.getElementById('alertHistory').innerHTML=`<div class="empty-filter">Alert service unavailable: ${escapeHtml(e.message)}</div>`}}
async function showAlertSettings(){if(dataMode!=='live')return toast('Alert preferences are available in Live Data mode');try{alertSettings=alertSettings||await apiGet('/api/alerts/settings');const s=alertSettings,c=s.announcement_categories;const checks=Object.entries(s.category_labels).map(([key,label])=>`<label class="alert-setting-check"><input type="checkbox" name="${escapeHtml(key)}" ${c[key]?'checked':''}><span>${escapeHtml(label)}</span></label>`).join('');document.getElementById('dialogContent').innerHTML=`<div class="dialog-label">PORTFOLIO RULES · PERSISTED</div><h2 class="dialog-title">Alert preferences</h2><form id="alertSettingsForm"><div class="alert-setting-group"><strong>Announcement categories</strong>${checks}</div><div class="alert-setting-grid"><label>Positive daily move (%)<input type="number" name="positive" min="0.1" max="50" step="0.1" value="${s.positive_price_move_pct}"></label><label>Negative daily move (%)<input type="number" name="negative" min="0.1" max="50" step="0.1" value="${s.negative_price_move_pct}"></label><label>Volume vs 20-session average (×)<input type="number" name="volume" min="1" max="20" step="0.1" value="${s.unusual_volume_multiple}"></label></div><p class="dialog-copy">Rules use portfolio holdings and completed EOD market sessions. Price and volume data are sourced from Yahoo Finance via yfinance.</p><div class="dialog-actions"><button type="submit">Save preferences</button></div></form>`;document.getElementById('detailDialog').showModal();document.getElementById('alertSettingsForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const announcement_categories={};Object.keys(s.category_labels).forEach(k=>announcement_categories[k]=f.get(k)==='on');try{alertSettings=await apiGet('/api/alerts/settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({announcement_categories,positive_price_move_pct:Number(f.get('positive')),negative_price_move_pct:Number(f.get('negative')),unusual_volume_multiple:Number(f.get('volume'))})});document.getElementById('detailDialog').close();toast('Alert preferences saved');await refreshAlerts()}catch(err){toast(`Could not save alert preferences: ${err.message}`)}})}catch(e){toast(`Could not load alert settings: ${e.message}`)}}
function startupNotice(message,mode='loading'){const host=document.querySelector('#todayView .demo-notice');const origin=`API origin: ${API_BASE_URL||'not configured'}${API_BASE_URL?' · ':'. '}`;if(mode==='loading'){host.innerHTML=`<span class="notice-icon">i</span><span><strong>Connecting to FINN</strong> — ${escapeHtml(message)} · ${escapeHtml(origin)}</span>`;return}host.innerHTML=`<span class="notice-icon">!</span><span><strong>${mode==='error'?'Connection problem':mode==='ready'?'Live data ready':'Connected with limited data'}</strong> — ${escapeHtml(message)} · ${escapeHtml(origin)}</span>${mode==='error'?'<button class="startup-retry" id="startupRetry">Retry</button><button class="startup-demo" id="startupDemo">Use Demo Data</button>':'<button class="startup-retry" id="startupRetry">Retry</button>'}`;host.querySelector('#startupRetry')?.addEventListener('click',initializeApp);host.querySelector('#startupDemo')?.addEventListener('click',setDemoData)}
async function initializeApp(){const generation=++initGeneration;if(!API_BASE_URL){dataMode='unavailable';updateModeChrome();const message='This page was opened as a local file and no API origin is configured. Start the FastAPI server and open FINN at the matching http://127.0.0.1:8001 address.';startupNotice(message,'error');document.getElementById('activityList').innerHTML='<div class="empty-filter">Open FINN through the FastAPI server to load persisted portfolio data. No demo data was substituted.</div>';document.getElementById('businessDescription').textContent='Connect to the FastAPI app to load official company data.';document.getElementById('financialCoverage').textContent='API origin not configured.';return}dataMode='connecting';companies=[];announcements=[];digestAnnouncements=[];researchUniverse=[];sourceDocuments=[];selectedCompany=null;apiStatus=null;digestMeta=null;startupNotice('Checking API health and stored data.');renderHoldings();renderActivity();renderSaved();renderCompany();document.getElementById('modeLabel').textContent='CONNECTING';document.getElementById('freshnessLabel').textContent='Checking backend';document.getElementById('activityList').innerHTML='<div class="empty-filter">Connecting to backend…</div>';document.getElementById('financialCoverage').textContent='Connecting to backend…';document.getElementById('companyName').textContent='Loading company research';try{const health=await apiGet('/api/health');if(generation!==initGeneration)return;if(health.status!=='ok')throw new Error(health.database==='connected'?'Health endpoint returned an unexpected status.':'Database unavailable.');const status=await apiGet('/api/data-status');if(generation!==initGeneration)return;if(status.database_status!=='connected')throw new Error('Backend reached; database is unavailable.');apiStatus=status;await loadLiveData();if(generation!==initGeneration||dataMode!=='live')return;const gaps=[];if(!companies.length)gaps.push('database connected but no portfolio companies are registered');if(!apiStatus?.latest_market_date)gaps.push('portfolio loaded, but no EOD market observation is stored');if(!apiStatus?.announcement_count)gaps.push('portfolio loaded, but no announcements are stored');if(!apiStatus?.document_count)gaps.push('portfolio loaded, but no source documents are stored');if(!apiStatus?.financial_observation_count)gaps.push('portfolio loaded, but no financial observations are stored');const failedProviders=Object.entries(apiStatus?.sources||{}).filter(([,run])=>run&&['failed','partial','partial_failure'].includes(run.status)).map(([provider,run])=>`${provider} ${run.status}${run.error_summary?`: ${run.error_summary}`:''}`);if(apiStatus?.freshness?.market_stale)gaps.push('stored market data is stale');if(apiStatus?.freshness?.announcements_stale)gaps.push('stored announcements are stale');const issues=[liveError,...failedProviders,...gaps].filter(Boolean);const message=issues.length?`Backend and database connected with limited data: ${issues.join(' · ')}. Previously stored records remain available.`:'Backend, database and persisted data are connected. Portfolio, EOD prices, announcements, financials and source documents are loaded.';startupNotice(message,issues.length?'partial':'ready')}catch(e){if(generation!==initGeneration)return;dataMode='unavailable';companies=[];announcements=[];digestAnnouncements=[];researchUniverse=[];sourceDocuments=[];selectedCompany=null;const detail=String(e.message||e);const kind=/database unavailable/i.test(detail)?'Backend reached, database unavailable':/failed to fetch|networkerror|load failed/i.test(detail)?`No response from ${API_BASE_URL}; check that the server is running at this host and port`:`Health/API check failed at ${API_BASE_URL}: ${detail}`;startupNotice(kind,'error');document.getElementById('activityList').innerHTML=`<div class="empty-filter">${escapeHtml(kind)} · retry the connection or explicitly switch to Demo Data.</div>`;document.getElementById('financialCoverage').textContent=`Persisted financial data is unavailable because the API did not connect. ${API_BASE_URL}`;renderHoldings();renderCompany();updateModeChrome();document.getElementById('modeLabel').textContent='CONNECTION ERROR';document.getElementById('freshnessLabel').textContent='API connection unavailable'}}
function setSelectOptions(select,items,firstLabel){const current=select.value;select.innerHTML=`<option value="all">${escapeHtml(firstLabel)}</option>`+[...new Set(items)].filter(Boolean).sort().map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join('');if([...select.options].some(o=>o.value===current))select.value=current}
function updateModeChrome(){
  const live=dataMode==='live', demo=dataMode==='demo', unavailable=dataMode==='unavailable', connecting=dataMode==='connecting';
  document.body.classList.toggle('live-mode',live);
  document.getElementById('modeLabel').textContent=live?'LIVE DATA':demo?'DEMO DATA':connecting?'CONNECTING':'BACKEND ERROR';
  document.getElementById('freshnessLabel').textContent=live?(apiStatus?.latest_market_date?`EOD · ${apiStatus.latest_market_date}`:'Checking source freshness'):demo?'Illustrative fixtures':connecting?'Checking backend':'Connection unavailable';
  document.getElementById('marketStateText').textContent=live?(apiStatus?.latest_market_date?`EOD through ${apiStatus.latest_market_date}`:'EOD status unavailable'):demo?'Illustrative data':connecting?'Connecting':'Backend unavailable';
  document.getElementById('freshnessLabel').classList.toggle('stale',live&&(!apiStatus?.latest_market_date||!!liveError));
  const today=document.querySelector('#todayView .demo-notice'),research=document.querySelector('#researchView .demo-notice');
  const modeNotice=live?['Live source data','Prices are end-of-day from Yahoo Finance; dates refer to the latest stored completed session.']:demo?['Illustrative demo','Sample events and figures are fictional and shown for product demonstration.']:connecting?['Connecting to FINN','Checking the API and loading persisted portfolio data.']:['Backend unavailable','Live data has not loaded. Retry the connection or explicitly choose Demo Data.'];
  if(today){today.innerHTML=`<span class="notice-icon">i</span><span><strong>${modeNotice[0]}</strong> — ${modeNotice[1]}</span>${unavailable?'<button class="startup-retry" id="startupRetry">Retry</button><button class="startup-demo" id="startupDemo">Use Demo Data</button>':'<button aria-label="Dismiss notice" class="dismissModeNotice">×</button>'}`;today.querySelector('#startupRetry')?.addEventListener('click',initializeApp);today.querySelector('#startupDemo')?.addEventListener('click',setDemoData);today.querySelector('.dismissModeNotice')?.addEventListener('click',()=>today.remove())}
  if(research){research.innerHTML=`<span class="notice-icon">i</span><span><strong>${live?'Live source data':demo?'Illustrative demo':unavailable?'Backend unavailable':'Connecting to FINN'}</strong> — ${live?'Financial figures appear only after source review and link to the original filing.':demo?'No live financial data or sourced company claims are displayed.':unavailable?'Connect to FastAPI to access source-backed research.':'Loading persisted company research.'}</span>`}
}
function updateBriefing(){if(dataMode==='live'){renderDigestSummary();return}const card=document.getElementById('briefingCard');card.style.display='flex';}
function updatePortfolioSummary(){const count=dataMode==='live'?(digestMeta?.total||0):announcements.length;document.getElementById('developmentCount').textContent=dataMode==='live'?`${count} filings in selected window`:`${count} developments to review`;document.querySelector('#todayView .section-head h2').innerHTML=dataMode==='live'?`Portfolio digest <span class="muted-count">${String(count).padStart(2,'0')}</span>`:`Worth your attention <span class="muted-count">03</span>`;if(dataMode==='live')renderDigestSummary();else{document.getElementById('signalHeading').textContent='3 developments surfaced';document.getElementById('signalDescription').textContent='Prioritised by potential impact, new information and portfolio relevance.';document.getElementById('signalHigh').textContent='1';document.getElementById('signalMedium').textContent='1';document.getElementById('signalRoutine').textContent='1';document.getElementById('signalNote').textContent='Illustrative demo rules; not an investment recommendation.'}updateBriefing()}
function renderDocuments(){const docs=sourceDocuments.filter(d=>!selectedCompany||d.ticker===selectedCompany.ticker);const transcripts=docs.filter(d=>d.document_type==='earnings_call_transcript').length;if(!managementSummary)document.getElementById('commitmentDocCount').textContent=dataMode==='live'?`${transcripts} transcripts available`:'Illustrative demo';document.getElementById('sourceCoverageTitle').textContent=docs.length?`${docs.length} source documents found`:'No documents connected';document.getElementById('sourceCoverageText').textContent=docs.length?'Official company materials catalogued; see each source link.':dataMode==='live'?'Official investor-relations documents are not configured for this issuer yet.':'Annual reports and earnings calls will appear here.';document.querySelector('.coverage-dot').style.background=docs.length?'#75bd91':'#6d796e';document.getElementById('sourceDocumentList').innerHTML=docs.slice(0,4).map(d=>{const url=safeUrl(d.download_url)||safeUrl(d.landing_page_url);return `<div class="source-document"><span>${escapeHtml(d.title)} · ${escapeHtml(d.document_type.replaceAll('_',' '))}</span>${url?`<a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">Open ↗</a>`:''}</div>`}).join('')}
async function loadCompanyDocuments(ticker){if(dataMode!=='live')return;try{const result=await apiGet(`/api/documents?ticker=${encodeURIComponent(ticker)}`);if(dataMode!=='live'||selectedCompany?.ticker!==ticker)return;sourceDocuments=result.items||[];renderDocuments()}catch(e){if(dataMode!=='live'||selectedCompany?.ticker!==ticker)return;sourceDocuments=[];renderDocuments();document.getElementById('sourceCoverageTitle').textContent='Document source unavailable';document.getElementById('sourceCoverageText').textContent=e.message}}
async function loadCompanyProfile(ticker){if(dataMode!=='live')return;businessProfile=null;try{const result=await apiGet(`/api/company-profile/${encodeURIComponent(ticker)}`);if(dataMode!=='live'||selectedCompany?.ticker!==ticker)return;businessProfile=result;if(result.status==='available'){document.getElementById('businessDescription').textContent=result.facts.map(f=>f.text).join(' ');document.querySelector('.illustrative-inline').textContent=`Official annual report · ${result.facts.map(f=>`p.${f.page_number}`).join(', ')}`;document.getElementById('segmentTags').innerHTML=result.segments.map(s=>`<a href="${escapeHtml(s.source_url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(s.name)} · p.${s.page_number}</a>`).join('');document.querySelector('.segment-caption').textContent=result.document_title}else{document.getElementById('businessDescription').textContent=result.message||'Official company profile is not available.';document.querySelector('.illustrative-inline').textContent='No verified issuer profile connected';document.getElementById('segmentTags').innerHTML='';document.querySelector('.segment-caption').textContent='Source coverage is issuer-specific.'}}catch(e){if(dataMode==='live'&&selectedCompany?.ticker===ticker){document.getElementById('businessDescription').textContent=`Official business profile unavailable: ${e.message}`;document.querySelector('.illustrative-inline').textContent='Source service unavailable';document.getElementById('segmentTags').innerHTML=''}}}
function showResearchSection(section){researchSection=section;history.replaceState(null,'',section==='commitments'?'#commitments':'#research');document.querySelectorAll('.company-tabs button').forEach(b=>b.classList.toggle('selected',(b.dataset.tab||'overview')===section));document.querySelector('.research-grid').hidden=section==='commitments';document.getElementById('commitmentsView').hidden=section!=='commitments';if(section==='financials'){document.querySelector('.research-grid').hidden=false;document.getElementById('financialMetrics').scrollIntoView({behavior:'smooth',block:'center'})}if(section==='documents'){document.querySelector('.research-grid').hidden=false;document.getElementById('sourceDocumentList').scrollIntoView({behavior:'smooth',block:'center'})}if(section==='commitments'&&dataMode==='live'&&selectedCompany)loadManagement(selectedCompany.ticker)}
async function loadManagement(ticker){const host=document.getElementById('commitmentTimeline');host.innerHTML='<div class="empty-filter">Loading source-linked management statements…</div>';try{const [list,summary]=await Promise.all([apiGet(`/api/management-statements/${encodeURIComponent(ticker)}`),apiGet(`/api/commitments/${encodeURIComponent(ticker)}/summary`)]);if(dataMode!=='live'||selectedCompany?.ticker!==ticker)return;managementItems=list.items||[];managementSummary=summary;renderManagement()}catch(e){if(selectedCompany?.ticker===ticker)host.innerHTML=`<div class="empty-filter">Management intelligence unavailable: ${escapeHtml(e.message)}. Run extract-management-guidance for indexed transcripts.</div>`}}
function renderFreshness(){if(!apiStatus)return;const src=apiStatus.sources||{},refresh=apiStatus.latest_refresh;const providerLine=Object.entries(src).map(([name,run])=>`${name}: ${run?.status||'not run'}${run?.error_summary?` · ${run.error_summary}`:''}`).join(' · ');const lines=[`Market · ${apiStatus.latest_market_date||'no completed session stored'}`,`NSE filings · ${apiStatus.latest_announcement_ingestion?formatDateTime(apiStatus.latest_announcement_ingestion):'not ingested'} · ${apiStatus.announcement_count||0} records`,`Documents · ${src.tata_power_ir?.completed_at?formatDateTime(src.tata_power_ir.completed_at):'not synced'} · ${apiStatus.document_count||0} indexed`,`Financial extraction · ${apiStatus.latest_financial_extraction?formatDateTime(apiStatus.latest_financial_extraction):'not run'} · ${apiStatus.financial_observation_count||0} observations`,`Providers · ${providerLine||'no provider runs recorded'}`,`Last refresh · ${refresh?.completed_at?`${formatDateTime(refresh.completed_at)} · ${refresh.status}`:'not run'}`];document.getElementById('sourceFreshness').innerHTML=lines.map(x=>`<span>${escapeHtml(x)}</span>`).join('');document.getElementById('freshnessLabel').textContent=apiStatus.latest_market_date?`EOD · ${apiStatus.latest_market_date}`:'No EOD session stored';}
async function refreshStoredData(){if(dataMode!=='live')return toast('Switch to Live Data before refreshing sources');const status=document.getElementById('refreshProgress');const button=document.getElementById('refreshData');button.disabled=true;status.textContent='Starting controlled refresh…';try{const started=await apiGet('/api/refresh',{method:'POST'});status.textContent=started.already_running?'A refresh is already running; following its status.':'Refresh running · stored data remains available.';let job;for(let i=0;i<120;i++){await new Promise(resolve=>setTimeout(resolve,1500));job=await apiGet(`/api/refresh/${started.job_id}`);if(job.status!=='running')break;status.textContent=`Refresh running · ${Object.keys(job.details||{}).length} source groups complete.`}if(!job||job.status==='running'){status.textContent='Refresh is still running. Its status remains available in data-status.';return}const rows=Object.entries(job.details||{}).map(([name,value])=>`${name}: ${value.status||'unknown'}${value.error?` · ${value.error}`:''}`).join(' · ');status.textContent=`Refresh ${job.status}${rows?` · ${rows}`:''}${job.error_summary?` · ${job.error_summary}`:''}`;await loadLiveData()}catch(e){status.textContent=`Refresh could not start: ${e.message}`}finally{button.disabled=false}}
function renderManagement(){const ticker=selectedCompany?.ticker;const all=managementItems;const approved=all.filter(x=>x.review_status==='approved');let review=all.filter(x=>['needs_review','candidate'].includes(x.review_status));const candidateCategory=document.getElementById('commitmentCandidateCategory').value;if(candidateCategory!=='all')review=review.filter(x=>x.triage_category===candidateCategory);review.sort((a,b)=>({high:0,medium:1,low:2}[a.review_priority]??3)-({high:0,medium:1,low:2}[b.review_priority]??3));const counts=managementSummary||{};document.getElementById('commitmentSummary').innerHTML=`<span><b>${counts.approved_count||0}</b> approved</span><span><b>${counts.awaiting_outcome_count||0}</b> awaiting outcomes</span><span><b>${counts.assessed_count||0}</b> assessed</span><span><b>${counts.needs_review_count||0}</b> need review</span><button id="assessCommitments">Reassess approved guidance ↻</button>`;document.getElementById('assessCommitments').addEventListener('click',async()=>{try{await apiGet(`/api/commitments/${encodeURIComponent(ticker)}/assess`,{method:'POST'});await loadManagement(ticker)}catch(e){toast(`Could not assess commitments: ${e.message}`)}});document.getElementById('commitmentDocCount').textContent=`${counts.approved_count||0} approved · ${counts.needs_review_count||0} to review`;const financialTargets=approved.filter(x=>x.triage_category==='financial'&&x.target_low!==null&&x.target_period);const comparable=financialTargets.filter(x=>x.assessment?.financial_observation_id);const operationalCount=approved.filter(x=>x.triage_category==='operational').length;document.getElementById('narrativeNumbersNote').textContent=financialTargets.length?`${comparable.length} of ${financialTargets.length} approved financial targets have a linked comparable actual. Qualitative statements remain context only.`:`No approved, period-specific financial guidance target is currently available for a guidance-versus-actual verdict. ${operationalCount} approved operational commitments remain separate and are not scored against revenue or profit.`;
  const types=[...new Set(all.map(x=>x.statement_class))], periods=[...new Set(all.map(x=>x.target_period).filter(Boolean))], topics=[...new Set(all.map(x=>x.topic))];setSelectOptions(document.getElementById('commitmentTypeFilter'),types,'All statement types');setSelectOptions(document.getElementById('commitmentPeriodFilter'),periods,'All periods');setSelectOptions(document.getElementById('commitmentTopicFilter'),topics,'All topics');
  document.getElementById('commitmentReviewQueue').innerHTML=review.length?`<div class="review-queue-head"><strong>Analyst review queue</strong><span>${review.length} candidates · not verified commitments</span></div>`+review.slice(0,12).map(x=>`<article class="commitment-review-item"><div class="commitment-item-meta">${escapeHtml(x.transcript_date||'Date unavailable')} · ${escapeHtml(x.document_title)} · p.${x.page_number} · ${escapeHtml(x.speaker)} · ${escapeHtml(x.triage_category)} · ${escapeHtml(x.review_priority)} review priority</div><p>${escapeHtml(x.exact_quote)}</p><div class="commitment-review-controls"><input aria-label="Reviewer identifier for statement ${x.id}" placeholder="Reviewer identifier" id="reviewer-${x.id}"><button data-review="approved" data-id="${x.id}">Approve</button><button data-review="rejected" data-id="${x.id}">Reject</button><a href="${escapeHtml(x.source_url)}" target="_blank" rel="noopener noreferrer">Open transcript ↗</a></div></article>`).join(''):'<div class="review-queue-head"><strong>Analyst review queue</strong><span>No candidates currently need review.</span></div>';
  let shown=approved;const type=document.getElementById('commitmentTypeFilter').value,status=document.getElementById('commitmentStatusFilter').value,period=document.getElementById('commitmentPeriodFilter').value,topic=document.getElementById('commitmentTopicFilter').value;shown=shown.filter(x=>(type==='all'||x.statement_class===type)&&(period==='all'||x.target_period===period)&&(topic==='all'||x.topic===topic)&&(status==='all'||x.assessment?.status===status));document.getElementById('commitmentTimeline').innerHTML=shown.length?shown.map(x=>`<article class="commitment-entry"><div class="commitment-entry-date">${escapeHtml(x.transcript_date||'Date unavailable')}<small>${escapeHtml(x.document_title)} · p.${x.page_number}</small></div><div class="commitment-entry-body"><div class="commitment-item-meta"><span>${escapeHtml(x.statement_class.replaceAll('_',' '))}</span><span>${escapeHtml(x.topic)}</span><span>${escapeHtml(x.speaker)} · ${escapeHtml(x.designation||'designation not recorded')}</span></div><blockquote>${escapeHtml(x.exact_quote)}</blockquote><div class="commitment-target">${x.target_low!==null?`Target ${x.target_low}${x.target_high!==x.target_low?`–${x.target_high}`:''} ${escapeHtml(x.unit||'')}`:'No explicit numeric target'}${x.target_period?` · ${escapeHtml(x.target_period)}`:''}</div><div class="assessment-state"><strong>${escapeHtml(x.assessment?.status||'awaiting assessment')}</strong><span>${escapeHtml(x.assessment?.explanation||'Assessment has not been run yet.')}</span></div><div class="commitment-evidence"><a href="${escapeHtml(x.source_url)}" target="_blank" rel="noopener noreferrer">Open original transcript · page ${x.page_number} ↗</a>${x.assessment?.financial_observation_id?`<button data-evidence="${x.assessment.financial_observation_id}">Open reported outcome ↗</button>`:''}</div></div></article>`).join(''):'<div class="empty-filter">No approved statements match these filters. Review candidates above; unapproved statements are never shown as verified commitments.</div>';
  document.querySelectorAll('[data-review]').forEach(button=>button.addEventListener('click',async()=>{const id=button.dataset.id;const reviewer=document.getElementById(`reviewer-${id}`).value.trim();if(!reviewer)return toast('Enter the analyst reviewer identifier');try{await apiGet(`/api/management-statements/${id}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:button.dataset.review,reviewer,note:'Source quotation and speaker checked against indexed transcript page.'})});await loadManagement(ticker)}catch(e){toast(`Review could not be saved: ${e.message}`)}}));}
async function apiGet(path,options={}){if(!API_BASE_URL)throw new Error('API origin is not configured.');const response=await fetch(`${API_BASE_URL}${path}`,{...options,headers:{Accept:'application/json',...(options.headers||{})}});if(!response.ok){let message=`API request failed (${response.status})`;try{const body=await response.json();message=body.detail?.message||body.detail||message}catch{}throw new Error(typeof message==='string'?message:JSON.stringify(message))}return response.json()}
async function loadCompanyMarket(ticker){if(dataMode!=='live')return;document.getElementById('companyLatestPrice').innerHTML='— <small>INR</small>';document.getElementById('companyPriceDate').textContent='Loading stored EOD record…';try{const summary=await apiGet(`/api/market/${encodeURIComponent(ticker)}/summary`);if(dataMode!=='live'||selectedCompany?.ticker!==ticker)return;companyMarket=summary;if(summary.status==='available'){document.getElementById('companyLatestPrice').innerHTML=`${escapeHtml(Number(summary.latest_close).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}))} <small>INR</small>`;document.getElementById('companyPriceDate').textContent=`EOD · ${escapeHtml(summary.latest_trading_date)} · ${escapeHtml(summary.source)}`}else document.getElementById('companyPriceDate').textContent='No stored market observations'}catch(e){if(dataMode!=='live'||selectedCompany?.ticker!==ticker)return;document.getElementById('companyPriceDate').textContent='Market provider unavailable';toast(`Could not load market data: ${e.message}`)}}
function financialAmount(value){return `₹${Number(value).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})} Cr`}
function comparisonText(item){if(!item||item.status!=='available')return item?.status==='needs_review'?'Comparison awaiting source review':'—';const n=Number(item.percentage_change);return `${n>0?'+':''}${n.toFixed(1)}%`}
function renderFinancialPlaceholders(state='live'){const cards=[['revenue','REVENUE'],['ebitda','EBITDA'],['pbt','PBT'],['pat','PAT']];document.getElementById('financialPeriod').textContent='Period unavailable';document.getElementById('financialBasis').textContent='Consolidated · INR crore';document.getElementById('financialCoverage').textContent=state==='demo'?'Illustrative placeholders · no sourced company figures':state==='error'?'Financial data service unavailable.':'Financial statements not yet processed.';document.getElementById('financialMetrics').innerHTML=cards.map(([key,label])=>`<article class="metric-card"><div class="metric-label">${label}<span>₹</span></div><strong>—</strong><small>${state==='error'?'Could not load financial data':'Awaiting source data'}</small></article>`).join('');document.getElementById('financialChart').innerHTML='<div class="chart-empty"><div class="chart-icon">⌁</div><strong>No verified quarterly series</strong><span>Actual reported values will appear when available.</span></div>'}
function renderFinancialResearch(){if(dataMode!=='live')return renderFinancialPlaceholders('demo');if(!selectedCompany||financialDataTicker!==selectedCompany.ticker||!financialHeadline?.period_end){renderFinancialPlaceholders(financialError?'error':'live');renderFinancialAnalysis();return}const labelMap={revenue:'REVENUE',ebitda:'EBITDA',pbt:'PBT',pat:'PAT'};const period=`${financialHeadline.fiscal_quarter&&financialPeriodType==='quarterly'?financialHeadline.fiscal_quarter+' ':''}${financialHeadline.fiscal_year||''}`.trim();document.getElementById('financialPeriod').textContent=period||'Latest reported period';document.getElementById('financialBasis').textContent=`${financialHeadline.statement_basis} · ${financialHeadline.unit}`;document.getElementById('financialSeriesLabel').textContent=`${financialPeriodType==='annual'?'Annual':'Quarterly'} income statement`;const validated=financialHeadline.metrics.filter(x=>x.status==='validated').length;document.getElementById('financialCoverage').textContent=financialError?`Financial data service unavailable: ${financialError}`:`${validated} of 4 headline metrics source-verified · ${selectedCompany.ticker}`;document.getElementById('financialMetrics').innerHTML=financialHeadline.metrics.map(m=>{const title=labelMap[m.metric]||m.metric.toUpperCase();if(m.status==='not_separately_disclosed')return `<article class="metric-card"><div class="metric-label">${title}<span>₹</span></div><strong class="metric-missing">Not separately disclosed</strong><small>Official statements reviewed</small></article>`;if(!m.observation)return `<article class="metric-card"><div class="metric-label">${title}<span>₹</span></div><strong>—</strong><small>${escapeHtml(m.message||'No reported value available')}</small></article>`;const o=m.observation;const verified=m.status==='validated';const shown=verified?financialAmount(o.normalised_value_in_crore):'Needs source review';const basisLine=`${escapeHtml(o.period_type==='annual'?o.fiscal_year:`${o.fiscal_quarter} ${o.fiscal_year}`)} · ${escapeHtml(o.statement_basis)}`;const source=verified?`<button class="metric-evidence" data-evidence="${o.id}">Source · page ${o.page_number} ↗</button>`:'<small>Not shown as a verified figure</small>';return `<article class="metric-card"><div class="metric-label">${title}<span>₹</span></div><strong>${shown}</strong><small>${basisLine} · ${escapeHtml(o.reported_unit)}</small><small class="metric-change">QoQ ${comparisonText(m.qoq)} · YoY ${comparisonText(m.yoy)}</small>${source}</article>`}).join('');renderFinancialChart();renderFinancialAnalysis()}
function renderFinancialChart(){const host=document.getElementById('financialChart');if(!host)return;const items=(financialHistories[financialPeriodType]?.[financialTrajectoryMetric]||[]).filter(x=>x.observation.extraction_status==='validated').slice(-8);document.getElementById('chartFooterText').textContent=`${financialPeriodType==='annual'?'Annual':'Quarterly'} values · INR crore · validated observations only.`;if(items.length<2){host.innerHTML=`<div class="chart-empty"><div class="chart-icon">⌁</div><strong>${financialPeriodType==='annual'?'Annual':'Quarterly'} ${financialTrajectoryMetric.toUpperCase()} history is incomplete</strong><span>FINN leaves gaps where the source does not support a verified value.</span></div>`;return}const values=items.map(x=>Number(x.observation.normalised_value_in_crore));const max=Math.max(...values)*1.12;const min=Math.min(0,Math.min(...values)*.88);const width=760,height=190,left=56,right=22,top=20,bottom=35;const x=i=>left+i*(width-left-right)/(items.length-1);const y=v=>top+(max-v)/(max-min)*(height-top-bottom);const points=values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');const labels=items.map((item,i)=>`<text x="${x(i)}" y="${height-9}" text-anchor="middle">${escapeHtml(item.observation.fiscal_quarter)} ${escapeHtml(item.observation.fiscal_year.replace('FY ',''))}</text>`).join('');const dots=items.map((item,i)=>`<circle cx="${x(i)}" cy="${y(values[i])}" r="4"><title>${escapeHtml(item.observation.fiscal_year)} · ${financialAmount(values[i])}</title></circle>`).join('');const grid=[0,.33,.66,1].map(f=>{const val=max-(max-min)*f;const yy=top+(height-top-bottom)*f;return `<line x1="${left}" x2="${width-right}" y1="${yy}" y2="${yy}"/><text x="${left-8}" y="${yy+3}" text-anchor="end">${Math.round(val).toLocaleString('en-IN')}</text>`}).join('');const metricLabel={revenue:'Revenue from Operations',pbt:'Profit before tax',pat:'Profit after tax'}[financialTrajectoryMetric];const coverageNote=items.length<4?`<p class="chart-coverage-note">Showing ${items.length} validated ${financialPeriodType==='annual'?'annual':'quarterly'} observations. Other periods are not yet available from registered source documents.</p>`:'';host.innerHTML=`${coverageNote}<div class="chart-live"><div class="chart-live-title"><span class="chart-live-title-name">${metricLabel}</span><span class="chart-live-title-meta">₹ crore · ${financialBasis}</span></div><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${metricLabel} in INR crore">${grid}<polyline points="${points}"/>${dots}${labels}</svg></div>`}
function renderFinancialAnalysis(){const host=document.getElementById('analysisCards');if(!host)return;if(!selectedCompany||financialDataTicker!==selectedCompany.ticker){document.getElementById('analysisSignals').innerHTML='';host.innerHTML='<p>Loading financial observations for the selected company…</p>';document.getElementById('analysisObservations').innerHTML='';return;}const metrics=['net_debt','debt_equity','current_ratio','free_cash_flow','operating_cash_to_pat'];const latest=[...(financialAnalysis?.derived||[])].map(x=>x.period_end).sort().at(-1);document.getElementById('analysisPeriod').textContent=latest?`As at ${latest}`:'Annual values';document.getElementById('analysisSignals').innerHTML=(financialAnalysis?.computed_signals||[]).map(x=>`<p>${escapeHtml(x.text)}</p>`).join('');if(!latest){host.innerHTML='<p>Validated annual balance-sheet and cash-flow rows are not available for this issuer.</p>';document.getElementById('analysisObservations').innerHTML='';return}host.innerHTML=metrics.map(key=>{const d=(financialAnalysis.derived||[]).find(x=>x.metric===key&&x.period_end===latest);if(!d||d.status!=='available')return `<article class="analysis-card"><span>${escapeHtml(d?.label||key.replaceAll('_',' '))}</span><strong>Unavailable</strong><small>Required source observations are missing or unvalidated.</small></article>`;const value=d.unit==='INR crore'?financialAmount(d.value):`${Number(d.value).toFixed(2)}×`;return `<article class="analysis-card"><span>${escapeHtml(d.label)}</span><strong>${value}</strong><small>${escapeHtml(d.formula)}</small><div>${(d.inputs||[]).filter(Boolean).map(o=>`<button class="metric-evidence" data-evidence="${o.id}">${escapeHtml(o.metric)} · p.${o.page_number} ↗</button>`).join('')}</div></article>`}).join('');const labels={total_assets:'Total assets',total_equity:'Total equity',borrowings_noncurrent:'Non-current borrowings',borrowings_current:'Current borrowings',cash_and_cash_equivalents:'Cash and cash equivalents',current_assets:'Current assets',current_liabilities:'Current liabilities',cash_from_operations:'Cash flow from operations',cash_from_investing:'Cash flow from investing',cash_from_financing:'Cash flow from financing',capital_expenditure_ppe:'Capital expenditure'};const periods=[...(financialAnalysis.series.revenue||[])].map(o=>o.period_end).sort();document.getElementById('analysisObservations').innerHTML=periods.map(period=>`<article class="financial-year-card"><h3>FY ending ${period.slice(0,4)}</h3>${Object.entries(labels).map(([metric,label])=>{const o=(financialAnalysis.series[metric]||[]).find(x=>x.period_end===period&&x.extraction_status==='validated');return `<div class="financial-observation-row"><span>${label}</span>${o?`<strong>${financialAmount(o.normalised_value_in_crore)}</strong><button class="metric-evidence" data-evidence="${o.id}">p.${o.page_number} source ↗</button>`:'<strong>Unavailable</strong>'}</div>`}).join('')}</article>`).join('')}

function renderThesisDrift(){const groupsHost=document.getElementById('thesisDriftGroups'),coverageHost=document.getElementById('thesisDriftCoverage'),summaryHost=document.getElementById('thesisDriftSummary');if(!groupsHost||!coverageHost)return;if(!selectedCompany){groupsHost.innerHTML='';coverageHost.textContent='Select a company to inspect data coverage.';return}if(thesisDriftError){document.getElementById('thesisDriftPeriod').textContent='Service unavailable';document.getElementById('thesisDriftIntro').textContent=`Thesis Drift could not load: ${thesisDriftError}`;groupsHost.innerHTML='';coverageHost.textContent='The source-backed signal service failed. Retry by switching companies or refreshing the page.';return}if(!thesisDrift||thesisDrift.ticker!==selectedCompany.ticker){document.getElementById('thesisDriftPeriod').textContent='Loading verified signals…';document.getElementById('thesisDriftIntro').textContent='Comparing validated financial observations and primary disclosures.';groupsHost.innerHTML='';coverageHost.textContent='Coverage is being checked.';return}document.getElementById('thesisDriftPeriod').textContent=thesisDrift.latest_period||'No validated period';document.getElementById('thesisDriftIntro').textContent=thesisDrift.coverage.coverage_state==='available'?`${thesisDrift.coverage.available_groups} of ${thesisDrift.coverage.total_groups} signal groups have source coverage · ${thesisDrift.statement_basis} basis.`:'No validated financial signal coverage is available for this company.';const statusLabel=s=>String(s||'insufficient_data').replaceAll('_',' ');const formattedValue=(value,unit)=>unit==='INR crore'?financialAmount(value):unit==='disclosures'?`${Number(value).toFixed(0)} matched filing${Number(value)===1?'':'s'}`:`${Number(value).toFixed(1)}${unit==='%'?'%':unit==='pp'?' pp':'×'}`;const metricValue=s=>s.current_value===null||s.current_value===undefined?'Unavailable':formattedValue(s.current_value,s.unit);const changed=(thesisDrift.what_changed||[]).slice(0,3);if(summaryHost)summaryHost.innerHTML=changed.length?`<div class="thesis-summary-heading">What changed since the previous reporting period?</div><ul>${changed.map(s=>`<li><span class="thesis-status status-${escapeHtml(s.status)}">${escapeHtml(statusLabel(s.status))}</span><span><strong>${escapeHtml(s.name)}:</strong> ${escapeHtml(s.explanation)}</span></li>`).join('')}</ul>`:'<div class="thesis-summary-heading">What changed since the previous reporting period?</div><p>No comparative change signal is available for this period.</p>';groupsHost.innerHTML=thesisDrift.signal_groups.filter(g=>g.coverage_state==='available').map(g=>`<article class="thesis-group"><div class="thesis-group-head"><h3>${escapeHtml(g.name)}</h3><span>${g.signals.length} signals</span></div>${g.signals.map(s=>`<div class="thesis-signal"><div class="thesis-signal-title"><strong>${escapeHtml(s.name)}</strong><span class="thesis-status status-${escapeHtml(s.status)}">${escapeHtml(statusLabel(s.status))}</span></div><div class="thesis-signal-values"><b>${escapeHtml(metricValue(s))}</b>${s.previous_value!==null&&s.previous_value!==undefined?`<span>Previous ${escapeHtml(formattedValue(s.previous_value,s.unit))}</span>`:''}</div><p>${escapeHtml(s.explanation)}</p>${s.formula?`<small>${escapeHtml(s.formula)}</small>`:''}<div class="thesis-evidence">${(s.supporting_observations||[]).map(o=>`<button class="metric-evidence" data-evidence="${o.id}">${escapeHtml(o.metric)} · p.${o.page_number} ↗</button>`).join('')}${(g.disclosures||[]).slice(0,2).map(d=>`<a href="${escapeHtml(d.url)}" target="_blank" rel="noopener">${escapeHtml(d.category)} · ${escapeHtml(d.date?.slice(0,10)||'filing')} ↗</a>`).join('')}</div>${s.next_step?`<small class="thesis-next-step">Next: ${escapeHtml(s.next_step)}</small>`:''}</div>`).join('')}</article>`).join('')||'<p class="thesis-empty">Validated observations for these signal groups are not yet available.</p>';const missing=thesisDrift.signal_groups.filter(g=>g.coverage_state!=='available').map(g=>`<li><strong>${escapeHtml(g.name)}:</strong> ${escapeHtml(g.signals.map(s=>s.explanation).join(' '))}</li>`).join('');coverageHost.innerHTML=`<p>${thesisDrift.coverage.validated_observation_count} validated observations were checked. Calculation rules: ${escapeHtml(thesisDrift.rule_version)}.</p><ul>${missing||'<li>All configured signal groups have at least one source-backed indicator.</li>'}</ul>`}
async function loadCompanyFinancials(ticker){if(dataMode!=='live')return;financialError=null;thesisDriftError=null;thesisDrift=null;financialHeadline=null;financialHistories={quarterly:{},annual:{}};financialAnalysis=null;financialDataTicker=ticker;document.getElementById('financialCoverage').textContent='Loading source-backed financial observations…';renderFinancialResearch();renderThesisDrift();const basis=financialBasis,periodType=financialPeriodType;try{const [headline,...rest]=await Promise.allSettled([apiGet(`/api/financials/${encodeURIComponent(ticker)}/headline?statement_basis=${basis}&period_type=${periodType}`),...['revenue','pbt','pat'].map(metric=>apiGet(`/api/financials/${encodeURIComponent(ticker)}/history?metric=${metric}&statement_basis=${basis}&period_type=${periodType}&periods=${periodType==='annual'?3:8}`)),apiGet(`/api/financials/${encodeURIComponent(ticker)}/analysis?statement_basis=${basis}&period_type=annual`),apiGet(`/api/research/${encodeURIComponent(ticker)}/thesis-drift?statement_basis=${basis}&period_type=annual&periods=3`)]);if(dataMode!=='live'||selectedCompany?.ticker!==ticker||periodType!==financialPeriodType||basis!==financialBasis)return;if(headline.status==='fulfilled')financialHeadline=headline.value;else financialError=headline.reason.message;['revenue','pbt','pat'].forEach((metric,i)=>{const r=rest[i];financialHistories[periodType][metric]=r.status==='fulfilled'?(r.value.data||[]):[]});const analysis=rest[3];if(analysis.status==='fulfilled')financialAnalysis=analysis.value;else financialAnalysis=null;const drift=rest[4];if(drift.status==='fulfilled')thesisDrift=drift.value;else thesisDriftError=drift.reason.message;renderFinancialResearch();renderThesisDrift()}catch(e){if(dataMode!=='live'||selectedCompany?.ticker!==ticker)return;financialError=e.message;thesisDriftError=e.message;renderFinancialResearch();renderThesisDrift()}}
async function askResearchQuestion(question){const host=document.getElementById('researchAnswer');host.innerHTML='<p>Checking stored company evidence…</p>';if(dataMode!=='live'||!selectedCompany){host.innerHTML='<p>Switch to Live Data and select a company to ask an evidence-grounded question.</p>';return}try{const result=await apiGet(`/api/research/${encodeURIComponent(selectedCompany.ticker)}/ask`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question})});if(selectedCompany?.ticker!==result.ticker)return;host.innerHTML=`<p class="answer-status">${escapeHtml(result.status==='abstained'?'Evidence unavailable':result.status==='partial'?'Partial evidence':'Evidence-grounded answer')} · ${escapeHtml(result.mode.replaceAll('_',' '))}</p><p>${escapeHtml(result.answer)}</p>${result.formula?`<small>${escapeHtml(result.formula)}</small>`:''}${result.citations?.length?`<div class="answer-citations">${result.citations.map(c=>`<a href="${escapeHtml(c.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(c.title)}${c.period?` · ${escapeHtml(c.period)}`:''}${c.page?` · p.${c.page}`:''} ↗</a>`).join('')}</div>`:''}`}catch(e){host.innerHTML=`<p>Research service unavailable: ${escapeHtml(e.message)}</p>`}}
async function showFinancialEvidence(observationId){try{const o=await apiGet(`/api/financial-observations/${observationId}`);document.getElementById('dialogContent').innerHTML=`<div class="dialog-label">PRIMARY SOURCE · ${escapeHtml(o.statement_basis.toUpperCase())}</div><h2 class="dialog-title">${escapeHtml(o.metric.toUpperCase())} · ${escapeHtml(o.fiscal_quarter)} ${escapeHtml(o.fiscal_year)}</h2><p class="dialog-copy">${escapeHtml(o.document_title)} · page ${o.page_number}</p><div class="dialog-data"><strong>Reported row</strong><br>${escapeHtml(o.row_label)}<br><br><strong>Column</strong><br>${escapeHtml(o.column_header)}<br><br><strong>Source text</strong><br>${escapeHtml(o.source_quote)}<br><br><strong>Raw value</strong> ${escapeHtml(o.reported_value_raw)} ${escapeHtml(o.reported_unit)}<br><strong>Normalised</strong> ${financialAmount(o.normalised_value_in_crore)}<br><strong>Extraction status</strong> ${escapeHtml(o.extraction_status)}</div><div class="dialog-actions"><a class="evidence-open" href="${escapeHtml(o.local_pdf_url)}" target="_blank" rel="noopener noreferrer">Open verified PDF at page ${o.page_number} ↗</a></div>`;document.getElementById('detailDialog').showModal()}catch(e){toast(`Could not load financial evidence: ${e.message}`)}}
async function loadLiveData(){dataMode='live';liveError=null;companyError=null;announcementError=null;apiStatus=null;companies=[];announcements=[];digestAnnouncements=[];sourceDocuments=[];researchUniverse=[];updateModeChrome();document.getElementById('freshnessLabel').textContent='Loading live sources…';document.getElementById('activityList').innerHTML='<div class="empty-filter">Loading selected portfolio window…</div>';const results=await Promise.allSettled([apiGet('/api/companies'),apiGet('/api/research-universe'),apiGet('/api/announcements?lookback_days=30&limit=500'),apiGet('/api/data-status'),apiGet('/api/market/NIFTY50/summary'),apiGet('/api/alerts/settings')]);if(dataMode!=='live')return;const [companyResult,researchResult,announcementResult,statusResult,niftyResult,settingsResult]=results;if(companyResult.status==='fulfilled')companies=companyResult.value.map(mapCompany);else companyError=`Portfolio API unavailable: ${companyResult.reason.message}`;if(researchResult.status==='fulfilled')researchUniverse=researchResult.value.items.map(mapCompany);if(announcementResult.status==='fulfilled')announcements=announcementResult.value.items.map(mapAnnouncement);else announcementError=`Announcement API unavailable: ${announcementResult.reason.message}`;if(statusResult.status==='fulfilled'){apiStatus=statusResult.value;renderFreshness()}if(settingsResult.status==='fulfilled')alertSettings=settingsResult.value;liveError=[companyError,announcementError].filter(Boolean).join(' · ')||null;const all=[...companies,...researchUniverse];selectedCompany=all.find(c=>c.ticker===selectedCompany?.ticker)||companies.find(c=>c.ticker==='TATAPOWER')||companies[0]||null;setSelectOptions(document.getElementById('priorityFilter'),['high','medium','routine'],'All materiality');setSelectOptions(document.getElementById('categoryFilter'),announcements.map(a=>a.category),'All categories');document.getElementById('priorityFilter').classList.add('priority-filter-live');renderHoldings();renderSaved();renderCompany();await loadDigest();await refreshAlerts();if(dataMode!=='live')return;if(niftyResult.status==='fulfilled'&&niftyResult.value.status==='available'){const n=niftyResult.value;document.querySelector('.market-mini strong').textContent=Number(n.latest_close).toLocaleString('en-IN',{maximumFractionDigits:2});document.querySelector('.market-mini .neutral-tag').textContent=`EOD · ${n.latest_trading_date}`;document.getElementById('marketStateText').textContent=`EOD through ${apiStatus?.latest_market_date||n.latest_trading_date}`}else document.querySelector('.market-mini strong').textContent='—';document.getElementById('todayFooterText').textContent=`Portfolio filings · EOD through ${apiStatus?.latest_market_date||'date unavailable'} · Yahoo Finance and NSE`;updatePortfolioSummary();updateModeChrome();if(liveError)toast(liveError);}
function setDemoData(){initGeneration++;dataMode='demo';managementItems=[];managementSummary=null;liveError=null;companyError=null;announcementError=null;apiStatus=null;sourceDocuments=[];researchUniverse=[];businessProfile=null;alertSettings=null;alertEvents=[];digestMeta=null;companies=[...demoCompanies];announcements=[...demoAnnouncements];digestAnnouncements=[...demoAnnouncements];selectedCompany=companies.find(c=>c.ticker==='TATAPOWER');showRoutine=false;document.getElementById('digestWindow').value='24h';document.getElementById('digestRange').textContent='Last 24 hours · illustrative demo';document.getElementById('digestCounts').innerHTML='';document.getElementById('todayFooterText').textContent='Data shown is illustrative · 09 Nov 2026';document.getElementById('priorityFilter').classList.remove('priority-filter-live');setSelectOptions(document.getElementById('priorityFilter'),['high','monitor','routine'],'All priorities');setSelectOptions(document.getElementById('categoryFilter'),['Results','Capital allocation','Compliance'],'All categories');document.querySelector('.market-mini strong').textContent='—';document.querySelector('.market-mini .neutral-tag').textContent='EOD data';document.getElementById('companyLatestPrice').innerHTML='— <small>INR</small>';document.getElementById('companyPriceDate').textContent='No live price connected';document.getElementById('refreshProgress').textContent='Demo mode is showing illustrative data.';renderHoldings();renderActivity();renderSaved();renderAlertHistory();renderCompany();updatePortfolioSummary();updateModeChrome()}
function showView(name){const isToday=name==='today';document.getElementById('todayView').classList.toggle('active',isToday);document.getElementById('researchView').classList.toggle('active',!isToday);document.getElementById('crumb').textContent=isToday?'Today':'Research';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));window.scrollTo({top:0,behavior:'smooth'});history.replaceState(null,'',`#${name}`)}
function showSearchResults(query){const box=document.getElementById('searchResults');const q=query.trim().toLowerCase();const all=[...companies,...researchUniverse];const list=q?all.filter(c=>c.name.toLowerCase().includes(q)||c.ticker.toLowerCase().includes(q)).slice(0,7):[];const exact=q.toUpperCase();const canSearch=dataMode==='live'&&/^[A-Z][A-Z0-9&-]{0,19}$/.test(exact)&&exact!=='NIFTY50'&&!all.some(c=>c.ticker===exact);box.innerHTML=list.map(c=>`<button class="search-result" data-result="${escapeHtml(c.ticker)}"><span class="holding-logo">${escapeHtml(c.monogram)}</span><span>${escapeHtml(c.name)}</span><small>${companies.some(x=>x.ticker===c.ticker)?'PORTFOLIO':'RESEARCH'}</small></button>`).join('')+(canSearch?`<button class="search-result research-ticker-action" data-research="${escapeHtml(exact)}"><span class="holding-logo">+</span><span>Research NSE ticker ${escapeHtml(exact)}</span><small>AD-HOC</small></button>`:'');box.classList.toggle('open',!!list.length||canSearch);box.querySelectorAll('[data-result]').forEach(b=>b.addEventListener('click',()=>{selectCompany(b.dataset.result);box.classList.remove('open')}));box.querySelector('[data-research]')?.addEventListener('click',()=>researchTicker(exact))}
async function researchTicker(ticker){const selectionAtStart=selectionGeneration;const box=document.getElementById('searchResults');if(dataMode!=='live')return toast('Switch to Live Data to research an NSE ticker');box.innerHTML='<div class="empty-filter">Retrieving completed EOD data and NSE filings…</div>';try{const result=await apiGet(`/api/research-universe/${encodeURIComponent(ticker)}`,{method:'POST'});const company=mapCompany({ticker:result.ticker,name:result.company,sector:null,exchange:'NSE',yfinance_symbol:`${result.ticker}.NS`});researchUniverse=[...researchUniverse.filter(c=>c.ticker!==company.ticker),company];const [profile,ann]=await Promise.allSettled([apiGet(`/api/companies/${encodeURIComponent(ticker)}`),apiGet(`/api/announcements?ticker=${encodeURIComponent(ticker)}&lookback_days=30&limit=300`)]);if(profile.status==='fulfilled')researchUniverse=researchUniverse.map(c=>c.ticker===ticker?mapCompany(profile.value):c);if(ann.status==='fulfilled'){announcements=[...announcements.filter(a=>a.ticker!==ticker),...ann.value.items.map(mapAnnouncement)];renderSaved()}if(selectionGeneration===selectionAtStart){selectedCompany=companyByTicker(ticker);renderCompany();renderHoldings()}box.classList.remove('open');document.getElementById('companySearch').value='';toast(`Research data loaded for ${ticker}${result.announcements.status==='unavailable'?'; NSE announcements unavailable':''}`)}catch(e){box.innerHTML=`<div class="empty-filter">${escapeHtml(e.message)}</div>`;toast(`Could not research ${ticker}: ${e.message}`)}}

document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){showView(nav.dataset.view);return}const holding=e.target.closest('[data-ticker]');if(holding){selectCompany(holding.dataset.ticker);showView('research');return}const investigate=e.target.closest('[data-company]');if(investigate){selectCompany(investigate.dataset.company);showView('research');return}});
document.getElementById('dataModeToggle').addEventListener('click',()=>dataMode==='live'?setDemoData():initializeApp());
document.getElementById('priorityFilter').addEventListener('change',()=>{if(document.getElementById('priorityFilter').value==='routine')showRoutine=true;renderActivity()});document.getElementById('categoryFilter').addEventListener('change',renderActivity);
document.getElementById('loadMore').addEventListener('click',()=>{showRoutine=!showRoutine;renderActivity()});
document.getElementById('digestWindow').addEventListener('change',()=>{const custom=document.getElementById('digestWindow').value==='custom';document.getElementById('digestCustom').hidden=!custom;if(!custom)loadDigest()});document.getElementById('applyDigestDates').addEventListener('click',loadDigest);
document.getElementById('openAlertSettings').addEventListener('click',showAlertSettings);document.getElementById('evaluateAlerts').addEventListener('click',async()=>{await refreshAlerts();toast('Alert rules evaluated against available portfolio data')});document.getElementById('refreshData').addEventListener('click',refreshStoredData);['commitmentCandidateCategory','commitmentTypeFilter','commitmentStatusFilter','commitmentPeriodFilter','commitmentTopicFilter'].forEach(id=>document.getElementById(id).addEventListener('change',renderManagement));
document.getElementById('dismissNotice').addEventListener('click',()=>document.querySelector('#todayView .demo-notice').remove());document.querySelector('.dismissResearch').addEventListener('click',()=>document.querySelector('#researchView .demo-notice').remove());
document.getElementById('companySearch').addEventListener('input',e=>showSearchResults(e.target.value));document.addEventListener('click',e=>{if(!e.target.closest('.company-search'))document.getElementById('searchResults').classList.remove('open')});
document.querySelector('.search-trigger').addEventListener('click',()=>{showView('research');document.getElementById('companySearch').focus()});document.getElementById('mobilePortfolio').addEventListener('click',()=>{showView('research');document.getElementById('companySearch').focus();toast('Choose a company from the portfolio or search for an NSE ticker')});
document.getElementById('askForm').addEventListener('submit',async e=>{e.preventDefault();const q=document.getElementById('askInput').value.trim();if(!q)return toast('Enter a question to begin');await askResearchQuestion(q);});
document.querySelectorAll('.suggested-questions button').forEach(b=>b.addEventListener('click',()=>{const q=b.textContent.replace('↗','').trim();document.getElementById('askInput').value=q;askResearchQuestion(q)}));
document.querySelectorAll('.company-tabs button').forEach(b=>b.addEventListener('click',()=>showResearchSection(b.dataset.tab||'overview')));document.querySelectorAll('.chart-period-tabs button').forEach(b=>b.addEventListener('click',()=>{financialPeriodType=b.dataset.period;b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));if(selectedCompany&&dataMode==='live')loadCompanyFinancials(selectedCompany.ticker)}));document.querySelectorAll('.trajectory-metrics button').forEach(b=>b.addEventListener('click',()=>{financialTrajectoryMetric=b.dataset.metric;b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));renderFinancialChart()}));document.getElementById('financialBasisSelect').addEventListener('change',e=>{financialBasis=e.target.value;if(selectedCompany&&dataMode==='live')loadCompanyFinancials(selectedCompany.ticker)});
document.addEventListener('click',e=>{const evidence=e.target.closest('[data-evidence]');if(evidence)showFinancialEvidence(evidence.dataset.evidence)});
['sourceMethod','chartSource','commitmentInfo','connectSources'].forEach(id=>document.getElementById(id).addEventListener('click',()=>{const copy={sourceMethod:'Research uses company annual reports, quarterly financial-result filings and official earnings-call transcripts. Market prices and exchange announcements use separate Day 2 feeds.',chartSource:'QoQ compares the reported quarter with the immediately prior quarter. YoY compares with the same quarter one year earlier. FINN computes both from verified observations with matching statement basis, currency and period duration.',commitmentInfo:'FINN records a measurable statement, its target period and source passage, then evaluates it against comparable reported results.',connectSources:'FINN indexes official annual reports, quarterly filings and earnings-call transcripts. Financial values appear only after source review.'};document.getElementById('dialogContent').innerHTML=`<div class="dialog-label">FINN · HOW IT WORKS</div><h2 class="dialog-title">Evidence before inference</h2><p class="dialog-copy">${copy[id]}</p><div class="dialog-data">Extracted values stay linked to the original PDF, page number, reported row and period column. Unverified figures are withheld from the live snapshot.</div>`;document.getElementById('detailDialog').showModal()}));
document.querySelector('.tiny-plus').addEventListener('click',()=>toast('Portfolio editing is not part of this prototype'));
document.querySelector('.company-more').addEventListener('click',()=>{showResearchSection('documents');document.getElementById('sourceDocumentList').scrollIntoView({behavior:'smooth',block:'center'})});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showView('research');document.getElementById('companySearch').focus()}if(e.key==='Escape')document.getElementById('searchResults').classList.remove('open')});

if(location.hash==='#commitments'){showView('research');showResearchSection('commitments')}else if(location.hash==='#research')showView('research');
initializeApp();
